mapper.select:
SELECT FROM fee_standard
ORDER BY id ASC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE fee_standard
fee_code = #{feeCode}, fee_name = #{feeName}, fee_type = #{feeType}, unit_price = #{unitPrice}, unit = #{unit}, charge_cycle = #{chargeCycle}, late_fee_rate = #{lateFeeRate}, status = #{status}, remark = #{remark},
WHERE id = #{id}
